package org.documentknowledge.documentmanagement.application.sharing;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.documentknowledge.identity.*;
import org.documentknowledge.documentmanagement.application.*;
import org.documentknowledge.documentmanagement.domain.*;
import org.documentknowledge.documentmanagement.application.sharing.SharingModels.*;
import org.documentknowledge.documentmanagement.application.sharing.SharingModels.Document;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DocumentShareServiceTest {
    final Actor actor=new Actor("https://issuer.example","one");
    final DocumentCaller caller=new DocumentCaller(actor,"tenant-a",()->AuthorityDecision.ALLOW);
    final UUID low=UUID.fromString("00000000-0000-0000-0000-000000000001"),high=UUID.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff");
    final AtomicInteger sql=new AtomicInteger(),reads=new AtomicInteger();
    List<Document> rows=new ArrayList<>();
    java.util.function.IntFunction<RequestScopedResourceAuthorityPort.Snapshot> override;
    List<String> requested=List.of();
    final SharingAdmission admission=new SharingAdmission();
    SharingDeadline deadline(){return SharingDeadline.request();}
    Document doc(UUID id){return new Document(id,"tenant-a",7,"development-restricted",1,Set.of(new AclRule(caller.principal(),Action.SHARE_TO_COLLECTION,AclRule.Effect.ALLOW)));}
    RequestScopedResourceAuthorityPort.Snapshot snapshot(AuthorityDecision route,AuthorityDecision item,String fingerprint){return new RequestScopedResourceAuthorityPort.Snapshot(actor,"tenant-a",DocumentShareService.ACTION,requested,route,requested.stream().collect(java.util.stream.Collectors.toMap(x->x,x->item)),fingerprint);}
    DocumentShareService service(){return new DocumentShareService(new DocumentShareStore(){public <T>T locked(String tenant,List<UUID> ids,SharingDeadline deadline,java.util.function.Function<List<Document>,T> work){sql.incrementAndGet();deadline.check();assertEquals(ids.stream().sorted(Comparator.comparing(UUID::toString)).toList(),ids);return work.apply(rows);}},(a,t,action,ids)->{requested=ids;int n=reads.incrementAndGet();return override==null?snapshot(AuthorityDecision.ALLOW,AuthorityDecision.ALLOW,"a".repeat(64)):override.apply(n);},admission);}
    DmFailure failure(int status,Runnable work){var failure=assertThrows(DmFailure.class,work::run);assertEquals(status,failure.status());return failure;}
    @Test void strictExactSortedCompleteSetAndOriginalIdentity(){rows=List.of(doc(high),doc(low));var result=service().assess(caller,List.of(new Expectation(high,7L),new Expectation(low,null)),deadline());assertEquals(actor,result.actor());assertEquals("tenant-a",result.tenant());assertEquals(DocumentShareService.ACTION,result.action());assertEquals(List.of(low,high),result.assessments().stream().map(Assessment::documentId).toList());assertEquals(2,reads.get());assertEquals(1,sql.get());}
    @Test void eligibilityReturnsOnlyCurrentAllowedAndBindsEveryRequestedId(){rows=List.of(doc(low));var result=service().discover(caller,List.of(high,low),deadline());assertEquals(List.of(low),result.eligible().stream().map(Assessment::documentId).toList());assertEquals("87713f3ba8e835a17b0860faebd034a6087a1968a63a5465d87b26bea7ad9186",result.requestedSetDigest());assertEquals(2,reads.get());}
    @Test void emptyAuthorizedSubsetIsSuccessButStrictNeverPartial(){rows=List.of();assertTrue(service().discover(caller,List.of(low),deadline()).eligible().isEmpty());failure(404,()->service().assess(caller,List.of(new Expectation(low,null)),deadline()));}
    @Test void denyOverridesAllowWithoutInspectionGrant(){var rules=new HashSet<>(doc(low).rules());rules.add(new AclRule(caller.principal(),Action.SHARE_TO_COLLECTION,AclRule.Effect.DENY));rows=List.of(new Document(low,"tenant-a",7,"development-restricted",1,rules));assertTrue(service().discover(caller,List.of(low),deadline()).eligible().isEmpty());failure(404,()->service().assess(caller,List.of(new Expectation(low,1L)),deadline()));}
    @Test void unknownAnywhereCannotBeSilentlyOmitted(){override=n->snapshot(AuthorityDecision.ALLOW,AuthorityDecision.UNAVAILABLE,"a".repeat(64));failure(503,()->service().discover(caller,List.of(low),deadline()));assertEquals(0,sql.get());}
    @Test void missingRouteIs404BeforeLookupAndUnknown503(){for(var decision:List.of(AuthorityDecision.DENY,AuthorityDecision.UNAVAILABLE)){override=n->snapshot(decision,AuthorityDecision.ALLOW,"a".repeat(64));failure(decision==AuthorityDecision.DENY?404:503,()->service().discover(caller,List.of(low),deadline()));}assertEquals(0,sql.get());}
    @Test void deniedResourceIsOmittedInEligibilityButNotStrict(){rows=List.of(doc(low));override=n->snapshot(AuthorityDecision.ALLOW,AuthorityDecision.DENY,"a".repeat(64));assertTrue(service().discover(caller,List.of(low),deadline()).eligible().isEmpty());failure(404,()->service().assess(caller,List.of(new Expectation(low,null)),deadline()));}
    @Test void finalDenyAndUnknownWinOverGenerationConflict(){rows=List.of(doc(low));for(var decision:List.of(AuthorityDecision.DENY,AuthorityDecision.UNAVAILABLE)){reads.set(0);override=n->snapshot(n==1?AuthorityDecision.ALLOW:decision,AuthorityDecision.ALLOW,n==1?"a".repeat(64):"b".repeat(64));failure(decision==AuthorityDecision.DENY?404:503,()->service().assess(caller,List.of(new Expectation(low,0L)),deadline()));}}
    @Test void currentAllowGenerationChangeRequiresFreshRequestInBothTypes(){rows=List.of(doc(low));override=n->snapshot(AuthorityDecision.ALLOW,AuthorityDecision.ALLOW,n%2==1?"a".repeat(64):"b".repeat(64));assertEquals("STALE_AUTHORITY",failure(409,()->service().assess(caller,List.of(new Expectation(low,7L)),deadline())).code());assertEquals("STALE_AUTHORITY",failure(409,()->service().discover(caller,List.of(low),deadline())).code());}
    @Test void staleRevisionAfterCurrentAuthorization(){rows=List.of(doc(low));assertEquals("STALE_POLICY",failure(409,()->service().assess(caller,List.of(new Expectation(low,6L)),deadline())).code());rows=List.of();failure(404,()->service().assess(caller,List.of(new Expectation(low,6L)),deadline()));}
    @Test void malformedInputsNeverEnterSql(){for(List<Expectation> values:Arrays.asList(null,List.<Expectation>of(),Collections.nCopies(101,new Expectation(low,null)),List.of(new Expectation(low,-1L)),List.of(new Expectation(low,9_007_199_254_740_992L)),List.of(new Expectation(null,null))))failure(400,()->service().assess(caller,values,deadline()));failure(400,()->service().discover(caller,null,deadline()));failure(422,()->service().assess(caller,List.of(new Expectation(low,null),new Expectation(low,7L)),deadline()));assertEquals(0,sql.get());}
    @Test void exactHundredDocumentsAndSafeRevisionBound(){List<UUID> ids=new ArrayList<>();for(int i=1;i<=100;i++)ids.add(new UUID(0,i));rows=ids.stream().map(this::doc).toList();assertEquals(100,service().discover(caller,ids,deadline()).eligible().size());rows=List.of(new Document(low,"tenant-a",9_007_199_254_740_991L,"development-restricted",1,doc(low).rules()));assertEquals(9_007_199_254_740_991L,service().assess(caller,List.of(new Expectation(low,9_007_199_254_740_991L)),deadline()).assessments().getFirst().documentRevision());}
    @Test void malformedProjectionNeverBecomesEvidence(){for(Document invalid:List.of(new Document(low,"tenant-a",-1,"development-restricted",1,doc(low).rules()),new Document(low,"tenant-a",9_007_199_254_740_992L,"development-restricted",1,doc(low).rules()),new Document(low,"tenant-a",1,"public",1,doc(low).rules()),new Document(low,"tenant-a",1,"development-restricted",2,doc(low).rules()),new Document(low,"other",1,"development-restricted",1,doc(low).rules()),doc(high))){rows=List.of(invalid);failure(503,()->service().discover(caller,List.of(low),deadline()));}rows=List.of(doc(low),doc(low));failure(503,()->service().discover(caller,List.of(low),deadline()));rows=null;failure(503,()->service().discover(caller,List.of(low),deadline()));}
    @Test void foreignAndWrongActionAclCannotAuthorize(){for(var rule:List.of(new AclRule(new Principal(actor.issuer(),"other"),Action.SHARE_TO_COLLECTION,AclRule.Effect.ALLOW),new AclRule(caller.principal(),Action.INSPECT_DRAFT,AclRule.Effect.ALLOW))){rows=List.of(new Document(low,"tenant-a",1,"development-restricted",1,Set.of(rule)));assertTrue(service().discover(caller,List.of(low),deadline()).eligible().isEmpty());}}
    @Test void wrongSnapshotBindingAndExceptionsFailClosed(){rows=List.of(doc(low));override=n->{throw new IllegalStateException("not public");};failure(503,()->service().discover(caller,List.of(low),deadline()));override=n->null;failure(503,()->service().discover(caller,List.of(low),deadline()));override=n->snapshot(AuthorityDecision.ALLOW,AuthorityDecision.ALLOW,"invalid");failure(503,()->service().discover(caller,List.of(low),deadline()));for(int variant=0;variant<4;variant++){int v=variant;override=n->new RequestScopedResourceAuthorityPort.Snapshot(v==0?new Actor(actor.issuer(),"other"):actor,v==1?"other":"tenant-a",v==2?"document.read":DocumentShareService.ACTION,v==3?List.of(high.toString()):requested,AuthorityDecision.ALLOW,Map.of(v==3?high.toString():low.toString(),AuthorityDecision.ALLOW),"a".repeat(64));failure(503,()->service().discover(caller,List.of(low),deadline()));}}
    @Test void unavailableDefaultCannotBorrowScalarAuthority(){rows=List.of(doc(low));var unavailable=new DocumentShareService(new DocumentShareStore(){public<T>T locked(String t,List<UUID> i,SharingDeadline d,java.util.function.Function<List<Document>,T>w){throw new AssertionError("No SQL");}},RequestScopedResourceAuthorityPort.unavailable(),admission);failure(503,()->unavailable.discover(caller,List.of(low),deadline()));}
    @Test void membershipIsRecheckedAtTransmission(){rows=List.of(doc(low));AtomicInteger calls=new AtomicInteger();var changing=new DocumentCaller(actor,"tenant-a",()->calls.incrementAndGet()==1?AuthorityDecision.ALLOW:AuthorityDecision.DENY);failure(403,()->service().discover(changing,List.of(low),deadline()));for(var decision:List.of(AuthorityDecision.DENY,AuthorityDecision.UNAVAILABLE))failure(decision==AuthorityDecision.DENY?403:503,()->service().discover(new DocumentCaller(actor,"tenant-a",()->decision),List.of(low),deadline()));}
    @Test void admissionBeforeSqlSharedAcrossStrictAndEligibilityAndReleased(){rows=List.of(doc(low));try(var permit=admission.acquire(actor)){failure(503,()->service().assess(caller,List.of(new Expectation(low,null)),deadline()));failure(503,()->service().discover(caller,List.of(low),deadline()));assertEquals(0,sql.get());}assertEquals(1,service().discover(caller,List.of(low),deadline()).eligible().size());}
    @Test void globalCapacityAndIdempotentRelease(){List<SharingAdmission.Permit> permits=new ArrayList<>();for(int i=0;i<16;i++)permits.add(admission.acquire(new Actor(actor.issuer(),"p"+i)));failure(503,()->admission.acquire(actor));permits.getFirst().close();permits.getFirst().close();try(var permit=admission.acquire(actor)){assertNotNull(permit);}permits.forEach(SharingAdmission.Permit::close);}
    @Test void deadlineParentCancellationAndExactBoundaryRejectLateSql(){AtomicLong tick=new AtomicLong();SharingDeadline root=new SharingDeadline(tick::get,Duration.ofMillis(1500));SharingDeadline child=root.child(Duration.ofMillis(500));assertEquals(500_000_000,child.remainingNanos());root.cancel();failure(503,child::check);SharingDeadline expired=new SharingDeadline(tick::get,Duration.ofNanos(1));tick.set(1);failure(503,expired::remainingNanos);failure(503,()->service().discover(caller,List.of(low),expired));assertEquals(0,sql.get());}
    @Test void authenticationCompletionCannotRenewExpiredOwnership(){AtomicLong tick=new AtomicLong();SharingDeadline deadline=new SharingDeadline(tick::get,Duration.ofMillis(1500));override=n->{tick.set(1_500_000_000);return snapshot(AuthorityDecision.ALLOW,AuthorityDecision.ALLOW,"a".repeat(64));};failure(503,()->service().discover(caller,List.of(low),deadline));assertEquals(0,sql.get());}
}
